// Included inside Window. Import starts a new, unsaved conceptual document.
 bool previewRise(const RiseImport &source){
  QDialog dialog(this);dialog.setObjectName("risePreview");dialog.setWindowTitle(t("Importa modello RISE","Import RISE model"));QVBoxLayout layout(&dialog);
  auto intro=new QLabel(t("Controlla gli elementi recuperati e seleziona gli attributi che formano l’identificatore di ogni entità. Più spunte nella stessa entità formano un unico identificatore composto. Puoi importare una bozza e completarli in seguito.","Review recovered elements and select the attributes forming each entity's identifier. Multiple checks in one entity form a single composite identifier. You can import a draft and complete them later."));intro->setWordWrap(true);layout.addWidget(intro);
  QComboBox diagrams;diagrams.setObjectName("riseDiagram");for(const auto &d:source.diagrams)diagrams.addItem(d.name);if(source.diagrams.isEmpty())diagrams.addItem(t("Disposizione a griglia","Grid layout"));layout.addWidget(new QLabel(t("Disposizione da recuperare","Layout to recover")));layout.addWidget(&diagrams);
  QSplitter split;QTreeWidget keys;keys.setObjectName("riseKeys");keys.setHeaderLabels({t("Entità / attributo","Entity / attribute"),t("Indizio nel file","File hint")});
  for(const auto &e:source.model.objects)if(e.kind=="entity"){
   auto item=new QTreeWidgetItem(&keys,QStringList{e.name});item->setFlags(Qt::ItemIsEnabled);for(const auto &a:source.model.attributes(e.id)){
    auto child=new QTreeWidgetItem(item,QStringList{a.name,source.keyCandidates.contains(a.id)?t("Univoco e obbligatorio","Unique and required"):QString()});child->setData(0,Qt::UserRole,a.id);child->setFlags(Qt::ItemIsEnabled|Qt::ItemIsUserCheckable);child->setCheckState(0,Qt::Unchecked);child->setToolTip(0,t("Spunta per includere nell’identificatore concettuale. Gli indizi non equivalgono a una chiave primaria dichiarata.","Check to include in the conceptual identifier. Hints do not mean a declared primary key."));
   }
  }
  keys.expandAll();keys.resizeColumnToContents(0);QTextBrowser report;report.setObjectName("riseReport");report.setPlainText(source.report(en));split.addWidget(&keys);split.addWidget(&report);split.setStretchFactor(0,1);split.setStretchFactor(1,1);layout.addWidget(&split,1);
  QLabel pending;pending.setWordWrap(true);layout.addWidget(&pending);auto update=[&]{int missing=0;for(int i=0;i<keys.topLevelItemCount();++i){auto parent=keys.topLevelItem(i);bool any=false;for(int j=0;j<parent->childCount();++j)any|=parent->child(j)->checkState(0)==Qt::Checked;missing+=!any;}pending.setText(t("Entità senza identificatore selezionato: ","Entities without a selected identifier: ")+QString::number(missing)+t(". Le sottoclassi possono ereditare l’identificatore. F7 verificherà la bozza importata.",". Subclasses may inherit their identifier. F7 will validate the imported draft."));};connect(&keys,&QTreeWidget::itemChanged,&dialog,[&]{update();});update();
  QDialogButtonBox buttons(QDialogButtonBox::Cancel);auto apply=buttons.addButton(t("Importa come nuovo progetto","Import as new project"),QDialogButtonBox::AcceptRole);apply->setObjectName("applyRiseImport");layout.addWidget(&buttons);connect(&buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(&buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.resize(1040,730);
  if(dialog.exec()!=QDialog::Accepted)return false;
  Model imported=source.positioned(diagrams.currentIndex());for(int i=0;i<keys.topLevelItemCount();++i){auto parent=keys.topLevelItem(i);for(int j=0;j<parent->childCount();++j){auto child=parent->child(j);imported.get(child->data(0,Qt::UserRole).toString())->key=child->checkState(0)==Qt::Checked;}}
  if(!maybeSave())return false;
  ++documentEpoch;model={};filePath.clear();selection.clear();selectionIds.clear();history.clear();logicalView=false;uml=true;buildMenus();change(t("Importa RISE","Import RISE"),[=](Model &m){m=imported;});fit();status->setText(t("RISE importato nel concettuale. Verifica con F7 e salva come .schema.","RISE imported into the conceptual model. Validate with F7 and save as .schema."));return true;
 }
 bool importRisePath(const QString &path){RiseImport imported;QString error;if(!loadRise(path,imported,error,en)){QMessageBox::warning(this,t("Importazione RISE non riuscita","RISE import failed"),error);return false;}return previewRise(imported);}
 void importRiseDialog(){auto path=QFileDialog::getOpenFileName(this,t("Importa RISE","Import RISE"),filePath,t("Modelli RISE (*.rise)","RISE models (*.rise)"));if(!path.isEmpty())importRisePath(path);}
